<script setup lang="ts">
import {computed, onMounted, ref} from 'vue'
import BaseDialog from '../../../components/BaseDialog.vue'
import BaseSelect from '../../../components/BaseSelect.vue'
import {del, get, patch, post, request} from '../../../utils/request'
import {useAuthStore} from '../../../stores/auth'

type Role = 'member' | 'admin' | 'owner'
interface User { username: string; role: Role; point: number; message_count: number; online_time: number; create_time: string; registered: boolean }
interface Page { page: number; total: number; total_pages: number; has_previous: boolean; has_next: boolean }
interface PointLog { id: number; action: 'add' | 'remove'; num: number; reason: string; ext: string | null; create_at: string }
const authStore = useAuthStore(); const isOwner = computed(() => authStore.user?.role === 'owner')
const users = ref<User[]>([]); const loading = ref(false); const loaded = ref(false); const error = ref('')
const keyword = ref(''); const role = ref('全部角色'); const registered = ref('全部状态'); const page = ref(1); const total = ref(0); const totalPages = ref(1); const hasPrevious = ref(false); const hasNext = ref(false)
const detailOpen = ref(false); const detail = ref<any>(null); const detailError = ref('')
const createOpen = ref(false); const createName = ref(''); const createPassword = ref(''); const createError = ref(''); const createLoading = ref(false)
const pointsOpen = ref(false); const pointsTarget = ref<User | null>(null); const pointsAction = ref('增加'); const pointsAmount = ref(''); const pointsReason = ref(''); const pointsError = ref(''); const pointsLoading = ref(false)
const passwordOpen = ref(false); const passwordTarget = ref<User | null>(null); const newPassword = ref(''); const passwordError = ref(''); const passwordLoading = ref(false)
const deleteOpen = ref(false); const deleteTarget = ref<User | null>(null); const deleteError = ref(''); const deleteLoading = ref(false)
const roleOpen = ref(false); const roleTarget = ref<User | null>(null); const newRole = ref('member'); const roleError = ref(''); const roleLoading = ref(false)
const pointLogsOpen = ref(false); const pointLogsTarget = ref<User | null>(null); const pointLogs = ref<PointLog[]>([]); const pointLogsError = ref(''); const pointLogsLoading = ref(false)
let serial = 0
const roleOptions = ['全部角色', 'member', 'admin', 'owner']; const registeredOptions = ['全部状态', '已注册', '未注册']; const roleEditOptions = ['member', 'admin', 'owner']
function formatDate(value: string) { const date = new Date(value); return Number.isNaN(date.getTime()) ? value || '-' : new Intl.DateTimeFormat('zh-CN', {year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit'}).format(date) }
function formatTime(seconds: number) { const hours = Math.floor(seconds / 3600); return hours ? `${hours}h ${Math.floor(seconds % 3600 / 60)}m` : `${Math.floor(seconds / 60)}m` }
async function loadUsers(next = 1) { const current = ++serial; loading.value = true; error.value = ''; const query = new URLSearchParams({page: String(next), limit: '20'}); if (keyword.value.trim()) query.set('keyword', keyword.value.trim()); if (role.value !== '全部角色') query.set('role', role.value); if (registered.value !== '全部状态') query.set('registered', String(registered.value === '已注册')); try { const result = await get<{users: User[]; pagination: Page}>(`/api/admin/users?${query}`); if (current !== serial) return; users.value = result.users; page.value = result.pagination.page; total.value = result.pagination.total; totalPages.value = result.pagination.total_pages; hasPrevious.value = result.pagination.has_previous; hasNext.value = result.pagination.has_next; loaded.value = true } catch (e) { if (current === serial) { users.value = []; error.value = e instanceof Error ? e.message : '用户列表加载失败' } } finally { if (current === serial) loading.value = false } }
function search() { void loadUsers(1) }; function clearFilters() { keyword.value = ''; role.value = '全部角色'; registered.value = '全部状态'; search() }
async function openDetail(user: User) { detail.value = null; detailError.value = ''; detailOpen.value = true; try { detail.value = (await get<{user: unknown}>(`/api/admin/users/${encodeURIComponent(user.username)}`)).user } catch (e) { detailError.value = e instanceof Error ? e.message : '无法读取用户详情' } }
async function openPointLogs(user: User) { pointLogsTarget.value = user; pointLogs.value = []; pointLogsError.value = ''; pointLogsLoading.value = true; pointLogsOpen.value = true; try { pointLogs.value = (await get<{logs: PointLog[]}>(`/api/admin/users/${encodeURIComponent(user.username)}/point-logs`)).logs } catch (e) { pointLogsError.value = e instanceof Error ? e.message : '无法读取积分流水' } finally { pointLogsLoading.value = false } }
async function createUser() { if (createLoading.value) return; createLoading.value = true; createError.value = ''; try { await post('/api/admin/users', {username: createName.value, password: createPassword.value}); createOpen.value = false; createName.value = ''; createPassword.value = ''; await loadUsers(1) } catch (e) { createError.value = e instanceof Error ? e.message : '创建失败' } finally { createLoading.value = false } }
async function savePoints() { const user = pointsTarget.value, amount = Number(pointsAmount.value); if (!user || pointsLoading.value) return; pointsLoading.value = true; pointsError.value = ''; try { await patch(`/api/admin/users/${encodeURIComponent(user.username)}/points`, {action: pointsAction.value === '增加' ? 'add' : 'remove', amount, reason: pointsReason.value}); pointsOpen.value = false; await loadUsers(page.value) } catch (e) { pointsError.value = e instanceof Error ? e.message : '积分操作失败' } finally { pointsLoading.value = false } }
async function savePassword() { const user = passwordTarget.value; if (!user || passwordLoading.value) return; passwordLoading.value = true; passwordError.value = ''; try { await request(`/api/admin/users/${encodeURIComponent(user.username)}/password`, {method: 'PUT', body: JSON.stringify({password: newPassword.value})}); passwordOpen.value = false; newPassword.value = '' } catch (e) { passwordError.value = e instanceof Error ? e.message : '密码重置失败' } finally { passwordLoading.value = false } }
async function saveRole() { const user = roleTarget.value; if (!user || roleLoading.value) return; roleLoading.value = true; roleError.value = ''; try { await patch(`/api/admin/users/${encodeURIComponent(user.username)}/role`, {role: newRole.value}); roleOpen.value = false; await loadUsers(page.value) } catch (e) { roleError.value = e instanceof Error ? e.message : '角色修改失败' } finally { roleLoading.value = false } }
async function confirmDelete() { const user = deleteTarget.value; if (!user || deleteLoading.value) return; deleteLoading.value = true; deleteError.value = ''; try { await del(`/api/admin/users/${encodeURIComponent(user.username)}`); deleteOpen.value = false; await loadUsers(users.value.length === 1 && page.value > 1 ? page.value - 1 : page.value) } catch (e) { deleteError.value = e instanceof Error ? e.message : '删除失败' } finally { deleteLoading.value = false } }
function openPoints(user: User) { pointsTarget.value = user; pointsAction.value = '增加'; pointsAmount.value = ''; pointsReason.value = ''; pointsError.value = ''; pointsOpen.value = true }; function openPassword(user: User) { passwordTarget.value = user; newPassword.value = ''; passwordError.value = ''; passwordOpen.value = true }; function openRole(user: User) { roleTarget.value = user; newRole.value = user.role; roleError.value = ''; roleOpen.value = true }; function openDelete(user: User) { deleteTarget.value = user; deleteError.value = ''; deleteOpen.value = true }
onMounted(() => { void loadUsers() })
</script>

<template>
  <section class="users-panel">
    <header class="users-toolbar"><div><strong>用户管理</strong><small>{{ loaded ? `${total.toLocaleString()} 位用户` : '正在读取用户档案' }}</small></div><button type="button" @click="createOpen = true">新建用户</button></header>
    <form class="user-filters" @submit.prevent="search"><input v-model="keyword" placeholder="搜索用户名"><BaseSelect v-model="role" :options="roleOptions"/><BaseSelect v-model="registered" :options="registeredOptions"/><button type="submit">筛选</button><button type="button" class="plain" @click="clearFilters">重置</button></form>
    <div class="users-scroll"><div v-if="loading && !loaded" class="state">正在读取用户档案...</div><div v-else-if="error" class="state error">{{ error }}<button type="button" @click="loadUsers(page)">重试</button></div><div v-else-if="!users.length" class="state">没有符合条件的用户。</div><div v-else class="user-list"><article v-for="user in users" :key="user.username" class="user-card"><div class="user-main"><div class="avatar">{{ user.username.slice(0, 1).toUpperCase() }}</div><div><strong>{{ user.username }}</strong><span>{{ user.registered ? '已注册' : '未注册' }} · {{ formatDate(user.create_time) }}</span></div><em :class="`role-${user.role}`">{{ user.role }}</em></div><dl><div><dt>积分</dt><dd>{{ user.point.toLocaleString() }}</dd></div><div><dt>消息</dt><dd>{{ user.message_count.toLocaleString() }}</dd></div><div><dt>在线</dt><dd>{{ formatTime(user.online_time) }}</dd></div></dl><footer><button type="button" @click="openDetail(user)">详情</button><button type="button" @click="openPointLogs(user)">流水</button><button type="button" @click="openPoints(user)">积分</button><button v-if="isOwner || user.role !== 'owner'" type="button" @click="openPassword(user)">密码</button><button v-if="isOwner" type="button" @click="openRole(user)">角色</button><button class="danger" type="button" @click="openDelete(user)">删除</button></footer></article></div></div>
    <footer class="pager"><span>第 {{ page }} / {{ totalPages }} 页</span><div><button :disabled="!hasPrevious || loading" @click="loadUsers(page - 1)">上一页</button><button :disabled="!hasNext || loading" @click="loadUsers(page + 1)">下一页</button></div></footer>
    <BaseDialog :open="detailOpen" title="用户详情" @close="detailOpen = false"><div v-if="detail" class="detail"><strong>{{ detail.username }}</strong><span>角色：{{ detail.role }}</span><span>积分：{{ (detail.point / 100).toLocaleString() }}</span><span>消息：{{ detail.message_count }}</span><span>创建：{{ formatDate(detail.create_time) }}</span></div><p v-else>{{ detailError || '加载中...' }}</p></BaseDialog>
    <BaseDialog :open="pointLogsOpen" :title="`${pointLogsTarget?.username || ''} 的积分流水`" @close="pointLogsOpen = false"><div class="point-log-list"><p v-if="pointLogsLoading">正在读取流水...</p><p v-else-if="pointLogsError">{{ pointLogsError }}</p><p v-else-if="!pointLogs.length">暂无积分流水。</p><article v-for="log in pointLogs" v-else :key="log.id" :class="log.action"><strong>{{ log.action === 'add' ? '+' : '-' }}{{ (log.num / 100).toLocaleString() }}</strong><span>{{ log.reason }}</span><small>{{ formatDate(log.create_at) }}{{ log.ext ? ` · ${log.ext}` : '' }}</small></article></div></BaseDialog>
    <BaseDialog :open="createOpen" title="新建用户" @close="createOpen = false"><form class="form" @submit.prevent="createUser"><label>用户名<input v-model.trim="createName" maxlength="64" required></label><label>初始密码<input v-model="createPassword" minlength="6" maxlength="128" required type="password"></label><small v-if="createError">{{ createError }}</small><div><button type="button" @click="createOpen = false">取消</button><button :disabled="createLoading" type="submit">创建</button></div></form></BaseDialog>
    <BaseDialog :open="pointsOpen" title="调整积分" @close="pointsOpen = false"><form v-if="pointsTarget" class="form" @submit.prevent="savePoints"><strong>{{ pointsTarget.username }}</strong><BaseSelect v-model="pointsAction" :options="['增加', '扣除']"/><label>数量<input v-model="pointsAmount" min="0.01" step="0.01" required type="number"></label><label>原因<input v-model.trim="pointsReason" maxlength="200" required></label><small v-if="pointsError">{{ pointsError }}</small><div><button type="button" @click="pointsOpen = false">取消</button><button :disabled="pointsLoading" type="submit">确认</button></div></form></BaseDialog>
    <BaseDialog :open="passwordOpen" title="重置密码" @close="passwordOpen = false"><form v-if="passwordTarget" class="form" @submit.prevent="savePassword"><strong>{{ passwordTarget.username }}</strong><label>新密码<input v-model="newPassword" minlength="6" maxlength="128" required type="password"></label><small v-if="passwordError">{{ passwordError }}</small><div><button type="button" @click="passwordOpen = false">取消</button><button :disabled="passwordLoading" type="submit">保存</button></div></form></BaseDialog>
    <BaseDialog :open="roleOpen" title="修改角色" @close="roleOpen = false"><form v-if="roleTarget" class="form" @submit.prevent="saveRole"><strong>{{ roleTarget.username }}</strong><BaseSelect v-model="newRole" :options="roleEditOptions"/><small v-if="roleError">{{ roleError }}</small><div><button type="button" @click="roleOpen = false">取消</button><button :disabled="roleLoading" type="submit">保存</button></div></form></BaseDialog>
    <BaseDialog :open="deleteOpen" title="确认删除用户" @close="deleteOpen = false"><div class="form"><strong>{{ deleteTarget?.username }}</strong><p>删除后该用户无法登录，现有令牌将失效。</p><small v-if="deleteError">{{ deleteError }}</small><div><button type="button" @click="deleteOpen = false">取消</button><button class="danger" :disabled="deleteLoading" type="button" @click="confirmDelete">确认删除</button></div></div></BaseDialog>
  </section>
</template>

<style scoped>
.users-panel{display:flex;flex:1;flex-direction:column;min-height:0;margin-top:10px;overflow:hidden;color:var(--panel-text);background:var(--panel-bg);border:1px solid var(--border);border-radius:5px}.users-toolbar,.pager{display:flex;align-items:center;justify-content:space-between;padding:10px 12px;border-bottom:1px solid var(--border)}.users-toolbar div,.detail{display:grid;gap:3px}.users-toolbar strong{font-size:14px}.users-toolbar small,.user-main span,small{color:var(--muted-text);font-size:10px}button{cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}.users-toolbar button,.user-filters button,.pager button,.form button{height:34px;padding:0 10px;color:var(--accent-contrast);background:var(--accent);border:0;border-radius:4px;font-size:11px;font-weight:700}.user-filters{display:grid;grid-template-columns:minmax(180px,1fr) 120px 120px auto auto;gap:8px;padding:9px 12px;border-bottom:1px solid var(--border)}input{height:34px;min-width:0;padding:0 9px;color:var(--panel-text);background:var(--surface);border:1px solid var(--border);border-radius:4px;font-size:12px}.plain,.pager button{color:var(--panel-text)!important;background:var(--surface)!important;border:1px solid var(--border)!important}.users-scroll{flex:1;min-height:0;overflow-y:auto}.user-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(290px,1fr));gap:10px;padding:12px}.user-card{display:grid;gap:12px;padding:13px;background:var(--surface);border:1px solid var(--border);border-radius:5px}.user-main{display:grid;grid-template-columns:34px minmax(0,1fr) auto;gap:9px;align-items:center}.avatar{display:grid;place-items:center;width:34px;height:34px;color:var(--accent-contrast);background:var(--accent);border-radius:4px;font-weight:800}.user-main div:nth-child(2){display:grid;gap:3px;min-width:0}.user-main strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px}.user-main em{padding:3px 6px;border-radius:3px;font-size:9px;font-style:normal;font-weight:700}.role-owner{color:var(--accent-contrast);background:var(--danger)}.role-admin{color:var(--accent-contrast);background:var(--accent)}.role-member{color:var(--muted-text);background:var(--panel-bg)}dl{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin:0}dl div{padding-left:8px;border-left:2px solid var(--border)}dt{color:var(--muted-text);font-size:9px}dd{margin:3px 0 0;font-size:12px;font-weight:700}.user-card footer{display:grid;grid-auto-columns:minmax(0,1fr);grid-auto-flow:column;overflow:hidden;background:var(--panel-bg);border:1px solid var(--border);border-radius:5px}.user-card footer button{height:32px;min-width:0;padding:0 5px;color:var(--muted-text);background:transparent;border:0;font-size:11px;font-weight:700}.user-card footer button+button{border-left:1px solid var(--border)}.user-card footer button:hover{color:var(--panel-text);background:var(--surface-hover)}.user-card footer .danger{color:var(--danger)}.user-card footer .danger:hover{color:var(--accent-contrast);background:var(--danger)}.pager{border-top:1px solid var(--border);border-bottom:0;font-size:11px}.pager div{display:flex;gap:6px}.state{padding:40px;text-align:center;color:var(--muted-text)}.form{display:grid;gap:11px}.form label{display:grid;gap:5px;font-size:11px;font-weight:700}.form>div{display:flex;justify-content:flex-end;gap:7px}.form small{color:var(--danger)}.point-log-list{display:grid;gap:7px}.point-log-list p{margin:0;color:var(--muted-text);font-size:12px}.point-log-list article{display:grid;grid-template-columns:auto 1fr;gap:3px 9px;align-items:center;padding:9px 10px;background:var(--surface);border:1px solid var(--border);border-radius:4px}.point-log-list strong{font-size:13px}.point-log-list .add strong{color:var(--success)}.point-log-list .remove strong{color:var(--danger)}.point-log-list span{font-size:12px}.point-log-list small{grid-column:2}@media(max-width:680px){.user-filters{grid-template-columns:1fr 1fr}.user-filters input{grid-column:1/-1}.user-card footer{grid-auto-flow:initial;grid-template-columns:repeat(3,1fr)}.user-card footer button:nth-child(4){border-left:0;border-top:1px solid var(--border)}}
</style>
